namespace ghidra.app.plugin.core.debug.gui.tracermi.launcher;






using docking.widgets;
using ghidra.debug.api.tracermi;
using ghidra.debug.api.tracermi.TraceRmiLaunchOffer;
using ghidra.util;
using ghidra.util;

public class LaunchFailureDialog : OptionDialog {
	private static readonly string MSGPAT_PART_TOP = """
			<html><body width="400px">
			<h3>Failed to launch '%s' due to an exception:</h3>

			<tt>%s</tt>

			<h3>Troubleshooting</h3>
			<p>
			<b>Check the Terminal!</b>
			If no terminal is visible, check the menus: <b>Window &rarr; Terminals &rarr;
			...</b>.
			A path or other configuration parameter may be incorrect.
			The back-end debugger may have paused for user input.
			There may be a missing dependency.
			There may be an incorrect version, etc.</p>

			""";
	private static readonly string MSGPAT_PART_RESOURCES = """
			<h3>These resources remain after the failed launch:</h3>
			<ul>
			%s
			</ul>

			<h3>How do you want to proceed?</h3>
			<ul>
			<li>Choose <b>Keep</b> to stop here and diagnose or complete the launch manually.</li>
			<li>Choose <b>Retry</b> to clean up and retry at the launch dialog.</li>
			<li>Choose <b>Cancel</b> to clean up without retrying.</li>
			</ul>
			""";
	private static readonly string MSGPAT_WITH_RESOURCES = MSGPAT_PART_TOP + MSGPAT_PART_RESOURCES;
	private static readonly string MSGPAT_WITHOUT_RESOURCES = MSGPAT_PART_TOP;
	private static readonly int MAX_TERM_CONTENT_LINES = 2;

	public class ErrPromptResponse
{	public static readonly ErrPromptResponse KEEP = new();
	public static readonly ErrPromptResponse RETRY = new();
	public static readonly ErrPromptResponse TERMINATE = new();

	}

	protected static string formatMessage(LaunchResult result) {
		return hasResources(result)
				? MSGPAT_WITH_RESOURCES.formatted(htmlProgramName(result),
					htmlExceptionMessage(result), htmlResources(result))
				: MSGPAT_WITHOUT_RESOURCES.formatted(htmlProgramName(result),
					htmlExceptionMessage(result));
	}

	protected static string htmlProgramName(LaunchResult result) {
		if (result.program() == null) {
			return "";
		}
		return "<tt>" + HTMLUtilities.escapeHTML(result.program().getName()) + "</tt>";
	}

	protected static string htmlExceptionMessage(LaunchResult result) {
		if (result.exception() == null) {
			return "(No exception)";
		}
		return HTMLUtilities.escapeHTML(result.exception().toString());
	}

	protected static bool hasResources(LaunchResult result) {
		return !result.sessions().isEmpty() ||
			result.acceptor() != null ||
			result.connection() != null ||
			result.trace() != null;
	}

	protected static string shorten(string title) {
		if (title.length() > 80) {
			return title.substring(0, 77) + "...";
		}
		return title;
	}

	protected static string htmlContent(TerminalSession session) {
		string content = session.content().trim();
		List<string> lines = Arrays.asList(content.split("\n"));
		string note = "";
		if (lines.size() >= MAX_TERM_CONTENT_LINES) {
			note = "(last %d lines)".formatted(MAX_TERM_CONTENT_LINES);
			content = lines.subList(lines.size() - MAX_TERM_CONTENT_LINES, lines.size())
					.stream()
					.collect(Collectors.joining("\n"));
		}
		return """
				<div style="font:bold;">Title: %s</div>%s
				<div style="background:black;color:white;">
				<pre>%s</pre>""".formatted(
			HTMLUtilities.escapeHTML(shorten(session.title())),
			note,
			content);
	}

	protected static string htmlResources(LaunchResult result) {
		StringBuilder sb = new StringBuilder();
		foreach (Entry<string, TerminalSession> ent in result.sessions().entrySet()) {
			TerminalSession session = ent.getValue();
			sb.append("<li>Terminal: %s &rarr; <tt>%s</tt>".formatted(
				HTMLUtilities.escapeHTML(ent.getKey()),
				HTMLUtilities.escapeHTML(session.description())));
			if (session.isTerminated()) {
				sb.append(" (Terminated)");
			}
			sb.append("<div>\n");
			sb.append(htmlContent(session));
			sb.append("</div>");
			sb.append("</li>\n");
		}
		if (result.acceptor() != null) {
			sb.append("<li>Acceptor: <tt>%s</tt></li>\n".formatted(
				HTMLUtilities.escapeHTML(result.acceptor().getAddress().toString())));
		}
		if (result.connection() != null) {
			sb.append("<li>Connection: <tt>%s</tt></li>\n".formatted(
				HTMLUtilities.escapeHTML(result.connection().getRemoteAddress().toString())));
		}
		if (result.trace() != null) {
			sb.append("<li>Trace: %s</li>\n".formatted(
				HTMLUtilities.escapeHTML(result.trace().getName())));
		}
		return sb.toString();
	}

	public static ErrPromptResponse show(LaunchResult result, HelpLocation helpLocation) {
		switch (new LaunchFailureDialog(result, helpLocation).show()) {
			case OptionDialog.YES_OPTION: return ErrPromptResponse.KEEP;
			case OptionDialog.NO_OPTION: return ErrPromptResponse.RETRY;
			case OptionDialog.CANCEL_OPTION: return ErrPromptResponse.TERMINATE;
			default: throw new AssertionError();
		};
	}

	protected LaunchFailureDialog(LaunchResult result, HelpLocation helpLocation) : base("Launch Failed", formatMessage(result), hasResources(result) ? "&Keep" : null,
			"&Retry", OptionDialog.ERROR_MESSAGE, null, true, "Retry")
    {
		setHelpLocation(helpLocation);
	}
}
